// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAudit The audit log, newest first
	// (GET /admin/audit)
	ListAudit(w http.ResponseWriter, r *http.Request, params ListAuditParams)
	// ExportAudit The filtered audit log as CSV (at most 100 000 rows)
	// (GET /admin/audit/export)
	ExportAudit(w http.ResponseWriter, r *http.Request, params ExportAuditParams)
	// GetBackups Database backups and the latest backup/scrub status
	// (GET /admin/backups)
	GetBackups(w http.ResponseWriter, r *http.Request)
	// RunBackup Back up the database now
	// (POST /admin/backups)
	RunBackup(w http.ResponseWriter, r *http.Request)
	// ListMasterBooks Browse the master store (every book the server holds)
	// (GET /admin/books)
	ListMasterBooks(w http.ResponseWriter, r *http.Request, params ListMasterBooksParams)
	// TrashBook Move a book to the Trash (hidden everywhere; purged after 30 days)
	// (DELETE /admin/books/{bookId})
	TrashBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// GetMasterBook One master-store book with its distributions
	// (GET /admin/books/{bookId})
	GetMasterBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// PurgeBook Permanently delete one trashed book and its files now
	// (POST /admin/books/{bookId}/purge)
	PurgeBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// RestoreBook Restore a book from the Trash
	// (POST /admin/books/{bookId}/restore)
	RestoreBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// LiftTakedown Lift a takedown (the book is visible again)
	// (DELETE /admin/books/{bookId}/takedown)
	LiftTakedown(w http.ResponseWriter, r *http.Request, bookId BookId)
	// TakeDownBook Hide a book from everyone now (files are kept; brief §6.5 rule 8)
	// (POST /admin/books/{bookId}/takedown)
	TakeDownBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// GetAdminDashboard Live sessions, server health, moderation inbox counts (brief §6.23)
	// (GET /admin/dashboard)
	GetAdminDashboard(w http.ResponseWriter, r *http.Request)
	// CreateDistribution Make a master-store book visible to a group or a user
	// (POST /admin/distributions)
	CreateDistribution(w http.ResponseWriter, r *http.Request)
	// RevokeDistribution Revoke a distribution
	// (DELETE /admin/distributions/{distributionId})
	RevokeDistribution(w http.ResponseWriter, r *http.Request, distributionId openapi_types.UUID)
	// ListDuplicates Books that look like duplicates, for review (brief §6.13)
	// (GET /admin/duplicates)
	ListDuplicates(w http.ResponseWriter, r *http.Request, params ListDuplicatesParams)
	// ScanDuplicates Look for duplicates now (also runs weekly)
	// (POST /admin/duplicates/scan)
	ScanDuplicates(w http.ResponseWriter, r *http.Request)
	// ResolveDuplicate Keep both books, or merge them into one
	// (POST /admin/duplicates/{duplicateId})
	ResolveDuplicate(w http.ResponseWriter, r *http.Request, duplicateId openapi_types.UUID)
	// ListGroups Groups
	// (GET /admin/groups)
	ListGroups(w http.ResponseWriter, r *http.Request)
	// CreateGroup Create a group
	// (POST /admin/groups)
	CreateGroup(w http.ResponseWriter, r *http.Request)
	// DeleteGroup Delete a group (the built-in Public group cannot be deleted)
	// (DELETE /admin/groups/{groupId})
	DeleteGroup(w http.ResponseWriter, r *http.Request, groupId GroupId)
	// UpdateGroup Rename a group or change its bandwidth priority
	// (PATCH /admin/groups/{groupId})
	UpdateGroup(w http.ResponseWriter, r *http.Request, groupId GroupId)
	// ListGroupMembers Members of a group
	// (GET /admin/groups/{groupId}/members)
	ListGroupMembers(w http.ResponseWriter, r *http.Request, groupId GroupId)
	// RemoveGroupMember Remove a user from a group
	// (DELETE /admin/groups/{groupId}/members/{userId})
	RemoveGroupMember(w http.ResponseWriter, r *http.Request, groupId GroupId, userId UserId)
	// AddGroupMember Add a user to a group
	// (PUT /admin/groups/{groupId}/members/{userId})
	AddGroupMember(w http.ResponseWriter, r *http.Request, groupId GroupId, userId UserId)
	// GetAdminGrowth Users, books, storage and listening per month
	// (GET /admin/growth)
	GetAdminGrowth(w http.ResponseWriter, r *http.Request, params GetAdminGrowthParams)
	// RunIntegrityCheck Re-hash every library file against its stored checksum now
	// (POST /admin/integrity-check)
	RunIntegrityCheck(w http.ResponseWriter, r *http.Request)
	// ScanLibrary Rescan the library folder now
	// (POST /admin/library/scan)
	ScanLibrary(w http.ResponseWriter, r *http.Request)
	// ListMetadataReview Books whose online match was too uncertain to apply ("needs review"), oldest first
	// (GET /admin/metadata-review)
	ListMetadataReview(w http.ResponseWriter, r *http.Request, params ListMetadataReviewParams)
	// DismissMetadataReview Keep a book's metadata as it is and clear "needs review"
	// (POST /admin/metadata-review/{bookId}/dismiss)
	DismissMetadataReview(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ListReports Reports, oldest open first (or newest first for closed ones)
	// (GET /admin/reports)
	ListReports(w http.ResponseWriter, r *http.Request, params ListReportsParams)
	// ResolveReport Close a report, and every other open report about the same thing
	// (POST /admin/reports/{reportId}/resolve)
	ResolveReport(w http.ResponseWriter, r *http.Request, reportId ReportId)
	// ListReviewQueue Requests to share books with Public, oldest first
	// (GET /admin/review-queue)
	ListReviewQueue(w http.ResponseWriter, r *http.Request, params ListReviewQueueParams)
	// ApproveReviewItem Approve a request (the book is shared with the group)
	// (POST /admin/review-queue/{itemId}/approve)
	ApproveReviewItem(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// RejectReviewItem Reject a request (a reason is required and shown to the uploader)
	// (POST /admin/review-queue/{itemId}/reject)
	RejectReviewItem(w http.ResponseWriter, r *http.Request, itemId ItemId)
	// UnhideReview Show a hidden review again
	// (DELETE /admin/reviews/{reviewId}/hide)
	UnhideReview(w http.ResponseWriter, r *http.Request, reviewId ReviewId)
	// HideReview Hide a review from everyone but its author (a reason is required)
	// (POST /admin/reviews/{reviewId}/hide)
	HideReview(w http.ResponseWriter, r *http.Request, reviewId ReviewId)
	// AdminRevokeSession Revoke any user's session
	// (DELETE /admin/sessions/{sessionId})
	AdminRevokeSession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// GetAdminSettings Instance settings (secrets are never returned, only whether they're set)
	// (GET /admin/settings)
	GetAdminSettings(w http.ResponseWriter, r *http.Request)
	// UpdateAdminSettings Change instance settings (groups and fields present are changed)
	// (PATCH /admin/settings)
	UpdateAdminSettings(w http.ResponseWriter, r *http.Request)
	// TestAdminSmtp Send a test email with the saved SMTP settings
	// (POST /admin/settings/smtp/test)
	TestAdminSmtp(w http.ResponseWriter, r *http.Request)
	// ListSignupRequests Sign-up requests (moderation inbox)
	// (GET /admin/signup-requests)
	ListSignupRequests(w http.ResponseWriter, r *http.Request, params ListSignupRequestsParams)
	// ApproveSignupRequest Approve a sign-up (user becomes active and joins Public)
	// (POST /admin/signup-requests/{requestId}/approve)
	ApproveSignupRequest(w http.ResponseWriter, r *http.Request, requestId RequestId)
	// DenySignupRequest Deny a sign-up
	// (POST /admin/signup-requests/{requestId}/deny)
	DenySignupRequest(w http.ResponseWriter, r *http.Request, requestId RequestId)
	// EmptyTrash Permanently delete everything in the Trash
	// (POST /admin/trash/empty)
	EmptyTrash(w http.ResponseWriter, r *http.Request)
	// GetUpdateStatus This server's version, the newest release, and the last update
	// (GET /admin/update)
	GetUpdateStatus(w http.ResponseWriter, r *http.Request)
	// StartUpdate Update the server now (needs the updater container)
	// (POST /admin/update)
	StartUpdate(w http.ResponseWriter, r *http.Request)
	// CheckForUpdate Look for a new release now (it is also checked daily)
	// (POST /admin/update/check)
	CheckForUpdate(w http.ResponseWriter, r *http.Request)
	// ListUserTags User tags (capability overrides, required 2FA)
	// (GET /admin/user-tags)
	ListUserTags(w http.ResponseWriter, r *http.Request)
	// CreateUserTag Create a user tag
	// (POST /admin/user-tags)
	CreateUserTag(w http.ResponseWriter, r *http.Request)
	// DeleteUserTag Delete a user tag (removes it from everyone)
	// (DELETE /admin/user-tags/{tagId})
	DeleteUserTag(w http.ResponseWriter, r *http.Request, tagId TagId)
	// UpdateUserTag Edit a user tag (fields present are changed)
	// (PATCH /admin/user-tags/{tagId})
	UpdateUserTag(w http.ResponseWriter, r *http.Request, tagId TagId)
	// ListUsers Users
	// (GET /admin/users)
	ListUsers(w http.ResponseWriter, r *http.Request, params ListUsersParams)
	// GetAdminUser One user with tags, groups and permissions
	// (GET /admin/users/{userId})
	GetAdminUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// PatchUser Change a user's status, role, quota or notice (a reason is required)
	// (PATCH /admin/users/{userId})
	PatchUser(w http.ResponseWriter, r *http.Request, userId UserId)
	// SetUserPermissions Replace a user's permission overrides (a missing key = use tags/defaults)
	// (PUT /admin/users/{userId}/permissions)
	SetUserPermissions(w http.ResponseWriter, r *http.Request, userId UserId)
	// CreatePasswordResetLink A one-time password reset link for a user (valid 24 h; stops working once used)
	// (POST /admin/users/{userId}/reset-link)
	CreatePasswordResetLink(w http.ResponseWriter, r *http.Request, userId UserId)
	// ListUserSessions A user's signed-in devices
	// (GET /admin/users/{userId}/sessions)
	ListUserSessions(w http.ResponseWriter, r *http.Request, userId UserId)
	// RemoveUserTag Take a tag off a user
	// (DELETE /admin/users/{userId}/tags/{tagId})
	RemoveUserTag(w http.ResponseWriter, r *http.Request, userId UserId, tagId TagId)
	// AddUserTag Give a user a tag
	// (PUT /admin/users/{userId}/tags/{tagId})
	AddUserTag(w http.ResponseWriter, r *http.Request, userId UserId, tagId TagId)
	// Login Log in with username + password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the current device session
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// ResetPassword Set a new password with a reset token (signs out all sessions)
	// (POST /auth/password-reset)
	ResetPassword(w http.ResponseWriter, r *http.Request)
	// RequestPasswordReset Email a password reset link ("forgot my password")
	// (POST /auth/password-reset/request)
	RequestPasswordReset(w http.ResponseWriter, r *http.Request)
	// RefreshTokens Exchange a refresh token for a new token pair (rotating)
	// (POST /auth/refresh)
	RefreshTokens(w http.ResponseWriter, r *http.Request)
	// Signup Request an account (creates a pending user awaiting admin approval)
	// (POST /auth/signup)
	Signup(w http.ResponseWriter, r *http.Request)
	// ConfirmTotp Confirm TOTP enrollment; returns the 10 one-time recovery codes
	// (POST /auth/totp/confirm)
	ConfirmTotp(w http.ResponseWriter, r *http.Request)
	// EnrollTotp Start TOTP enrollment (returns secret + otpauth URI)
	// (POST /auth/totp/enroll)
	EnrollTotp(w http.ResponseWriter, r *http.Request)
	// VerifyTotp Complete login with a TOTP code or a recovery code
	// (POST /auth/totp/verify)
	VerifyTotp(w http.ResponseWriter, r *http.Request)
	// GetAuthor Author page (books visible to me)
	// (GET /authors/{personId})
	GetAuthor(w http.ResponseWriter, r *http.Request, personId PersonId)
	// GetBook Book detail (files, chapters, my progress)
	// (GET /books/{bookId})
	GetBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// UpdateBookMetadata Edit a book's metadata (edited fields are locked; brief §6.12)
	// (PATCH /books/{bookId})
	UpdateBookMetadata(w http.ResponseWriter, r *http.Request, bookId BookId)
	// SetBookChapters Replace a book's chapters (book tools; editors only)
	// (PUT /books/{bookId}/chapters)
	SetBookChapters(w http.ResponseWriter, r *http.Request, bookId BookId)
	// DetectBookChapters Propose chapters from silences in the audio (book tools; editors only)
	// (POST /books/{bookId}/chapters/detect)
	DetectBookChapters(w http.ResponseWriter, r *http.Request, bookId BookId)
	// GetBookCover Cover image (resized variant)
	// (GET /books/{bookId}/cover)
	GetBookCover(w http.ResponseWriter, r *http.Request, bookId BookId, params GetBookCoverParams)
	// SetBookCoverFromUrl Use a cover image from a metadata provider (same permission as editing)
	// (PUT /books/{bookId}/cover)
	SetBookCoverFromUrl(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ExtractBookCover Use the cover embedded in the book's audio (book tools; editors only)
	// (POST /books/{bookId}/cover/embedded)
	ExtractBookCover(w http.ResponseWriter, r *http.Request, bookId BookId)
	// UploadBookCover Use an uploaded image as the cover (book tools; editors only)
	// (POST /books/{bookId}/cover/upload)
	UploadBookCover(w http.ResponseWriter, r *http.Request, bookId BookId)
	// GetBookFile Original audio file (supports HTTP Range)
	// (GET /books/{bookId}/files/{fileId})
	GetBookFile(w http.ResponseWriter, r *http.Request, bookId BookId, fileId openapi_types.UUID, params GetBookFileParams)
	// ListListeners Who's listening to (or finished) a book
	// (GET /books/{bookId}/listeners)
	ListListeners(w http.ResponseWriter, r *http.Request, bookId BookId)
	// MergeBookToM4b Merge a book's files into one chaptered m4b (book tools; editors only)
	// (POST /books/{bookId}/merge)
	MergeBookToM4b(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ListMetadataCandidates Look a book up with the metadata providers, best match first (editors only)
	// (GET /books/{bookId}/metadata/candidates)
	ListMetadataCandidates(w http.ResponseWriter, r *http.Request, bookId BookId, params ListMetadataCandidatesParams)
	// RefreshBookMetadata Run the metadata pipeline for a book again (editors only)
	// (POST /books/{bookId}/metadata/refresh)
	RefreshBookMetadata(w http.ResponseWriter, r *http.Request, bookId BookId)
	// RecommendBook Recommend a book to other people
	// (POST /books/{bookId}/recommend)
	RecommendBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ListReviews Ratings and reviews of a book, newest first, with the average
	// (GET /books/{bookId}/reviews)
	ListReviews(w http.ResponseWriter, r *http.Request, bookId BookId, params ListReviewsParams)
	// DeleteMyReview Delete your review of a book
	// (DELETE /books/{bookId}/reviews/mine)
	DeleteMyReview(w http.ResponseWriter, r *http.Request, bookId BookId)
	// PutMyReview Rate and review a book (creates or replaces your review; needs `can_review`)
	// (PUT /books/{bookId}/reviews/mine)
	PutMyReview(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ListBookShares Your shares of a book you uploaded, and your requests to share it publicly
	// (GET /books/{bookId}/shares)
	ListBookShares(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ShareBook Share a book you uploaded with a person or one of your groups
	// (POST /books/{bookId}/shares)
	ShareBook(w http.ResponseWriter, r *http.Request, bookId BookId)
	// UnshareBook Stop sharing (or withdraw a pending public request)
	// (DELETE /books/{bookId}/shares/{shareId})
	UnshareBook(w http.ResponseWriter, r *http.Request, bookId BookId, shareId ShareId)
	// CreateStreamUrl Signed, short-lived stream URLs for casting targets
	// (POST /books/{bookId}/stream-url)
	CreateStreamUrl(w http.ResponseWriter, r *http.Request, bookId BookId)
	// RegisterPush Register this device for push notifications
	// (POST /devices/push-subscription)
	RegisterPush(w http.ResponseWriter, r *http.Request)
	// UnregisterPush Stop push notifications for a device
	// (DELETE /devices/push-subscription/{deviceId})
	UnregisterPush(w http.ResponseWriter, r *http.Request, deviceId openapi_types.UUID)
	// GetHealth Liveness check (used by container healthchecks)
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetInstance Public instance information
	// (GET /instance)
	GetInstance(w http.ResponseWriter, r *http.Request)
	// GetJob Status of a background job you started (admins can see any)
	// (GET /jobs/{jobId})
	GetJob(w http.ResponseWriter, r *http.Request, jobId openapi_types.UUID)
	// ListLibrary My library (own uploads ∪ distributions, minus removed/hidden/filtered/taken down)
	// (GET /library)
	ListLibrary(w http.ResponseWriter, r *http.Request, params ListLibraryParams)
	// ListLibraryFacets Series, authors, narrators or tags in my library, with book counts
	// (GET /library/facets)
	ListLibraryFacets(w http.ResponseWriter, r *http.Request, params ListLibraryFacetsParams)
	// GetMe The current user
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Edit my profile and preferences
	// (PATCH /me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// ListBookmarks My bookmarks (optionally for one book)
	// (GET /me/bookmarks)
	ListBookmarks(w http.ResponseWriter, r *http.Request, params ListBookmarksParams)
	// CreateBookmark Add a bookmark
	// (POST /me/bookmarks)
	CreateBookmark(w http.ResponseWriter, r *http.Request)
	// DeleteBookmark Delete a bookmark (leaves a tombstone for other devices)
	// (DELETE /me/bookmarks/{bookmarkId})
	DeleteBookmark(w http.ResponseWriter, r *http.Request, bookmarkId BookmarkId)
	// UpdateBookmark Edit a bookmark (last write wins by client_ts)
	// (PATCH /me/bookmarks/{bookmarkId})
	UpdateBookmark(w http.ResponseWriter, r *http.Request, bookmarkId BookmarkId)
	// ListCollections My collections
	// (GET /me/collections)
	ListCollections(w http.ResponseWriter, r *http.Request)
	// CreateCollection Create a collection
	// (POST /me/collections)
	CreateCollection(w http.ResponseWriter, r *http.Request)
	// DeleteCollection Delete a collection (books are not affected)
	// (DELETE /me/collections/{collectionId})
	DeleteCollection(w http.ResponseWriter, r *http.Request, collectionId CollectionId)
	// UpdateCollection Rename or describe a collection (last write wins by client_ts)
	// (PATCH /me/collections/{collectionId})
	UpdateCollection(w http.ResponseWriter, r *http.Request, collectionId CollectionId)
	// RemoveFromCollection Remove a book from a collection
	// (DELETE /me/collections/{collectionId}/books/{bookId})
	RemoveFromCollection(w http.ResponseWriter, r *http.Request, collectionId CollectionId, bookId BookId)
	// AddToCollection Add a book to a collection
	// (PUT /me/collections/{collectionId}/books/{bookId})
	AddToCollection(w http.ResponseWriter, r *http.Request, collectionId CollectionId, bookId BookId)
	// ListCollectionShares Who a collection of yours is shared with
	// (GET /me/collections/{collectionId}/shares)
	ListCollectionShares(w http.ResponseWriter, r *http.Request, collectionId CollectionId)
	// ShareCollection Share a collection with a person or one of your groups
	// (POST /me/collections/{collectionId}/shares)
	ShareCollection(w http.ResponseWriter, r *http.Request, collectionId CollectionId)
	// UnshareCollection Stop sharing a collection with someone
	// (DELETE /me/collections/{collectionId}/shares/{shareId})
	UnshareCollection(w http.ResponseWriter, r *http.Request, collectionId CollectionId, shareId ShareId)
	// ListMyGroups The groups you belong to (share targets)
	// (GET /me/groups)
	ListMyGroups(w http.ResponseWriter, r *http.Request)
	// RemoveFromMyLibrary Remove a book from my view (restorable for 30 days; master copy is kept)
	// (DELETE /me/library/{bookId})
	RemoveFromMyLibrary(w http.ResponseWriter, r *http.Request, bookId BookId)
	// HideInMyLibrary Archive (hide) a book in my library
	// (POST /me/library/{bookId}/hide)
	HideInMyLibrary(w http.ResponseWriter, r *http.Request, bookId BookId)
	// RestoreToMyLibrary Restore a book from "Recently removed", or un-archive it
	// (POST /me/library/{bookId}/restore)
	RestoreToMyLibrary(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ChangeMyPassword Change my password (signs out my other devices)
	// (POST /me/password)
	ChangeMyPassword(w http.ResponseWriter, r *http.Request)
	// GetProgress My stored progress for a book
	// (GET /me/progress/{bookId})
	GetProgress(w http.ResponseWriter, r *http.Request, bookId BookId)
	// PutProgress Report playback position
	// (PUT /me/progress/{bookId})
	PutProgress(w http.ResponseWriter, r *http.Request, bookId BookId)
	// ListMyRecommendations Books other people recommended to you (only books you can see)
	// (GET /me/recommendations)
	ListMyRecommendations(w http.ResponseWriter, r *http.Request)
	// DismissRecommendation Dismiss a recommendation
	// (DELETE /me/recommendations/{recommendationId})
	DismissRecommendation(w http.ResponseWriter, r *http.Request, recommendationId RecommendationId)
	// RegenerateRecoveryCodes Replace my recovery codes (the old ones stop working)
	// (POST /me/recovery-codes)
	RegenerateRecoveryCodes(w http.ResponseWriter, r *http.Request)
	// RevokeMyOtherSessions Sign out all my other devices
	// (DELETE /me/sessions)
	RevokeMyOtherSessions(w http.ResponseWriter, r *http.Request)
	// ListMySessions My device sessions
	// (GET /me/sessions)
	ListMySessions(w http.ResponseWriter, r *http.Request)
	// RevokeMySession Revoke one of my sessions
	// (DELETE /me/sessions/{sessionId})
	RevokeMySession(w http.ResponseWriter, r *http.Request, sessionId SessionId)
	// GetMyStats My listening stats for a year (charts and year in review)
	// (GET /me/stats)
	GetMyStats(w http.ResponseWriter, r *http.Request, params GetMyStatsParams)
	// GetSyncDelta Everything that changed for me since a cursor
	// (GET /me/sync)
	GetSyncDelta(w http.ResponseWriter, r *http.Request, params GetSyncDeltaParams)
	// DisableMyTotp Turn off two-factor authentication
	// (POST /me/totp/disable)
	DisableMyTotp(w http.ResponseWriter, r *http.Request)
	// ListMyUploads My recent uploads and their processing status
	// (GET /me/uploads)
	ListMyUploads(w http.ResponseWriter, r *http.Request, params ListMyUploadsParams)
	// GetNarrator Narrator page (books visible to me)
	// (GET /narrators/{personId})
	GetNarrator(w http.ResponseWriter, r *http.Request, personId PersonId)
	// SearchPeople Find people to recommend or share to (active users in your groups)
	// (GET /people)
	SearchPeople(w http.ResponseWriter, r *http.Request, params SearchPeopleParams)
	// CreateReport Report a book, a review or a person to the admins
	// (POST /reports)
	CreateReport(w http.ResponseWriter, r *http.Request)
	// GetSeries Series page (books in order, visible to me)
	// (GET /series/{seriesId})
	GetSeries(w http.ResponseWriter, r *http.Request, seriesId openapi_types.UUID)
	// CompleteSetup Finish the wizard (creates the admin, stores settings, switches the server to normal mode)
	// (POST /setup/complete)
	CompleteSetup(w http.ResponseWriter, r *http.Request)
	// TestSetupDatabase Check that a database can be opened
	// (POST /setup/database/test)
	TestSetupDatabase(w http.ResponseWriter, r *http.Request)
	// TestSetupLibrary Check the library path exists and is writable (warns if empty)
	// (POST /setup/library/test)
	TestSetupLibrary(w http.ResponseWriter, r *http.Request)
	// TestSetupSmtp Send a test email with the given SMTP settings
	// (POST /setup/smtp/test)
	TestSetupSmtp(w http.ResponseWriter, r *http.Request)
	// GetSetupStatus Whether the first-run wizard still needs to run
	// (GET /setup/status)
	GetSetupStatus(w http.ResponseWriter, r *http.Request)
	// CreateSetupTotp Generate the first admin's TOTP secret (enrollment is mandatory)
	// (POST /setup/totp)
	CreateSetupTotp(w http.ResponseWriter, r *http.Request)
	// ListSharedCollections Collections other people shared with you or your groups
	// (GET /shared-collections)
	ListSharedCollections(w http.ResponseWriter, r *http.Request)
	// GetHlsPlaylist Low-bitrate HLS playlist for the whole book (generated on demand)
	// (GET /stream/{bookId}/hls/{profile}/index.m3u8)
	GetHlsPlaylist(w http.ResponseWriter, r *http.Request, bookId BookId, profile HlsProfile)
	// GetHlsSegment One 10 s HLS segment
	// (GET /stream/{bookId}/hls/{profile}/{segment})
	GetHlsSegment(w http.ResponseWriter, r *http.Request, bookId BookId, profile HlsProfile, segment string)
}

